 v jsonb;v_head jsonb;v_lines jsonb;v_details jsonb;v_record jsonb;
 v_id int;v_amt bigint;v_total bigint;v_idempotency uuid;
 v_session uuid;v_cat text;v_index int;v_headcount int;
begin
 select payment_session_id into v_session from taxpay_guest_private.demo_profiles where demo_id='user1';
 if v_session is null then raise exception 'user1 preview session is missing';end if;
 for v in select value from jsonb_array_elements(chunks) loop
  v_lines:='[]'::jsonb;v_total:=0;v_cat:=v->>'category';v_index:=(v->>'index')::int;
  for v_head in select value from jsonb_array_elements(v->'heads') loop
   v_id:=(v_head#>>'{}')::int;
   v_amt:=25000+v_id*111;v_total:=v_total+v_amt;
   v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
    'beneficiary','user1','category',v_cat,'assessmentYear','2026-27',
    'headId',v_id,'headNameEn',metadata->v_id::text->>'label',
    'economicCode',metadata->v_id::text->>'code',
    'amountMinor',v_amt,'taxAmount',v_amt::numeric/100,'totalAmount',v_amt::numeric/100,
    'note','Catalogue coverage fixture only; legal validity unverified'));
  end loop;
  v_idempotency:=md5(batch||':'||v_cat||':'||v_index)::uuid;
  v_details:=jsonb_build_object('fixtureBatch',batch,'sampleOnly',true,
    'scenario','ALL_ACTIVE_HEADS','payerId','user1','payerName','Individual Taxpayer 01',
    'taxpayerTin','1111111111111','payerMode','SELF','assessmentYear','2026-27',
    'lines',v_lines,'paymentChannel','NOW','paymentMethod','BANK_BRANCH',
    'receiptReference','SAMPLE-CAT-'||v_idempotency::text);
  v_record:=jsonb_build_object('origin','TAXPAY_SQL_FIXTURE','idempotencyKey',v_idempotency::text,
    'sessionId',v_session::text,'service',v_cat,'amountMinor',v_total,'details',v_details);
  insert into demo_payment.story_payments(idempotency_key,session_id,service_code,amount_minor,data,status)
    values(v_idempotency,v_session,v_cat,v_total,v_record,'SIMULATED_SUCCESS')
    on conflict(idempotency_key) do nothing;
 end loop;
 insert into demo_payment.story_notifications(payment_id,session_id,event_type)
 select p.id,p.session_id,'SIMULATED_PAYMENT_SUCCESS' from demo_payment.story_payments p
 where p.data->'details'->>'fixtureBatch'=batch
 and not exists(select 1 from demo_payment.story_notifications n where n.payment_id=p.id);
 if (select count(*) from demo_payment.story_payments p where p.data->'details'->>'fixtureBatch'=batch)<>jsonb_array_length(chunks)
 then raise exception 'Catalogue fixture missing';end if;
end;
$sweep$;
